<template><div class="premium-card p-5" data-testid="student-profile-card"><div class="flex items-center gap-4"><div class="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl text-sm font-black text-white shadow-md" :style="avatarStyle" aria-hidden="true">{{ initials }}</div><div class="min-w-0 flex-1"><p class="truncate font-bold text-slate-900">{{ user?.full_name || '—' }}</p><p class="mt-0.5 truncate text-xs text-slate-400">{{ user?.email || '' }}</p><p class="mt-2"><StatusBadge status="CONFIRMADA" :custom-map="{ CONFIRMADA:{label:roleLabel,class:'border-primary-100 bg-primary-50 text-primary-700',dot:'bg-primary-500'} }" test-id="profile-role-badge" /></p></div></div></div></template>
<script setup>
import { computed } from 'vue'; import { useTenantStore } from '../stores/tenant'; import StatusBadge from './StatusBadge.vue'
const props=defineProps({user:{type:Object,default:()=>({})},role:{type:String,default:'student'}}); const tenantStore=useTenantStore(); const roleLabel=computed(()=>({admin:'Administrador',student:'Aluno',super_admin:'Super Administrador'}[props.role?.toLowerCase()]||props.role||'—')); const initials=computed(()=>{const n=props.user?.full_name||'';if(!n)return'?';const p=n.trim().split(/\s+/);return p.length===1?p[0].slice(0,2).toUpperCase():(p[0][0]+p.at(-1)[0]).toUpperCase()}); const avatarStyle=computed(()=>({background:`linear-gradient(135deg,${tenantStore.primary_color||'#1B7A3A'},${tenantStore.secondary_color||'#17324D'})`}))
</script>
